   scroll.scrollTop=scroll.scrollHeight;scroll.dispatchEvent(new frame.contentWindow.Event('scroll'));await wait(()=>ui.collectionResults.length===43&&!ui.collectionSearching,'下滑超过四十篇');assert.equal(calls.filter(c=>c.type==='search').at(-1).page,2);assert.deepEqual(calls.filter(c=>c.type==='search').at(-1).researchScope,calls[0].researchScope);assert.isFalse(ui.collectionSearchState.hasMore);
