 it('downloads a real PDF into its chosen folder and lists only usable files in the discovery rail',async()=>{
  const {HttpServer}=ChromeUtils.importESModule('chrome://remote/content/server/httpd.sys.mjs'),httpd=new HttpServer(),collection=await createDataObject('collection',{name:'真实下载验收文件夹'});scopeCollections.push(collection);const fixture=getTestDataDirectory();fixture.append('test.pdf');httpd.registerFile('/paper.pdf',fixture);httpd.registerPathHandler('/missing.pdf',{handle(_request,response){response.setStatusLine(null,404,'Not Found');response.write('missing');}});httpd.start(-1);const base='http://127.0.0.1:'+httpd.identity.primaryPort,request=Zotero.HTTP.request,pdfFetch=E.fetchDiscoveryPDF,queue=E.manuscripts.queueArticle,stages=[],destination={libraryID:collection.libraryID,collectionID:collection.id},url='https://easysch-download-acceptance.invalid/paper.pdf',badURL='https://easysch-download-acceptance.invalid/missing.pdf';let saved;
  Zotero.HTTP.request=function(method,target,options){return request.call(this,method,target===url?base+'/paper.pdf':target===badURL?base+'/missing.pdf':target,options);};E.fetchDiscoveryPDF=(target,options)=>pdfFetch(target===url?base+'/paper.pdf':target===badURL?base+'/missing.pdf':target,options);E.manuscripts.queueArticle=()=>{};
  try{
   await win.ZoteroPane.collectionsView.selectCollection(collection.id);await workspace.show('discovery');ui=workspace.ui;frame=workspace.frame;
   saved=await E.obtainPaper({id:'native-real-pdf',title:'已保存的真实本地 PDF',url,pdf:url,oa:true},{...destination,open:false,onProgress:value=>stages.push(value.stage)});scopeFiles.push(saved.itemID);assert.isTrue(await IOUtils.exists(saved.path));assert.isAbove((await IOUtils.stat(saved.path)).size,100);assert.include(stages,'download');assert.include(stages,'save');assert.include(stages,'saved');
   const bad={id:'native-missing-pdf',title:'失败题录不能算已下载 PDF',url:badURL,pdf:badURL,oa:true},metadata=await E.importAcademic(bad,{...destination,select:false});scopeFiles.push(metadata.id);let failure;try{await E.obtainPaper(bad,{...destination,open:false});}catch(error){failure=error;}assert.exists(failure);assert.include(failure.message,'404');
   for(const rail of ui.agentFileRails)rail.render();await wait(()=>ui.$('view-search').querySelector('.workspace-output-row[data-output-id="download:'+saved.attachmentID+'"]'),'已下载文件进入左侧栏');const output=ui.$('view-search').querySelector('.workspace-output-section');assert.include(output.textContent,'已保存的真实本地 PDF');assert.include(output.textContent,collection.name);assert.notInclude(output.textContent,bad.title);assert.exists(output.querySelector('.workspace-output-open'));assert.exists(output.querySelector('.workspace-output-actions button'));assert.exists(ui.$('view-search').querySelector('.conversation-files-import'));assert.exists(ui.$('view-search').querySelector('.conversation-files-history'));
   report.actualDownloadedPDF={path:saved.path,attachmentID:saved.attachmentID,folder:collection.name,stages,failedMetadataExcluded:true};await snapshot('native-discovery-downloaded-pdf');
  }finally{Zotero.HTTP.request=request;E.fetchDiscoveryPDF=pdfFetch;E.manuscripts.queueArticle=queue;await new Promise(resolve=>httpd.stop(resolve));}
 });
